import{_ as e,o as i,c as a,ap as t}from"./chunks/framework.CuFS6FqL.js";const k=JSON.parse('{"title":"Project retention","description":"Keep local pentest project files only as long as needed. Set up Project Sense to delete stale data after 90 days.","frontmatter":{"title":"Project retention","description":"Keep local pentest project files only as long as needed. Set up Project Sense to delete stale data after 90 days."},"headers":[],"relativePath":"organization/human-resources/project-retention.md","filePath":"organization/human-resources/project-retention.md"}'),n={name:"organization/human-resources/project-retention.md"};function o(l,s,h,p,r,d){return i(),a("div",null,[...s[0]||(s[0]=[t(`<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /organization/human-resources/project-retention.md for this page in Markdown format</div><h1 id="project-retention" tabindex="-1">Project retention <a class="header-anchor" href="#project-retention" aria-label="Permalink to &quot;Project retention&quot;">​</a></h1><p>Customer and project data on your machine should not outlive its purpose. The <a href="/pentesting-manual/operation-rules">Pentest operation rules</a> suggests a dedicated directory for local pentest files. Delete anything you no longer need.</p><h2 id="project-sense" tabindex="-1">Project Sense <a class="header-anchor" href="#project-sense" aria-label="Permalink to &quot;Project Sense&quot;">​</a></h2><p><a href="https://gitlab.internal.syslifters.com/tools/project-sense" target="_blank" rel="noreferrer">Project Sense</a> is a small tool for Windows, Linux, and macOS that watches configured directories and deletes stale content. It runs on a schedule and writes a log of what it deleted, skipped, or kept.</p><p>Each direct child folder of an observation root counts as one <strong>project folder</strong>. The tool deletes a project folder when all files inside are older than <code>MaxAgeDays</code> (90 by default), or when the folder is empty.</p><p>To keep a project longer, place an empty <code>SKIP_DELETION</code> file in the project folder root. The folder is then skipped until you remove that file. Delete this flag file if the project is no longer needed.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><ol><li>Clone the repository and open <code>config.json</code>.</li><li>Set <code>ObservationRoots</code> to the directory where you store pentest projects (absolute path).</li><li>Set <code>Logfile</code> to an absolute path where you want the run log (e.g. <code>C:\\Logs\\ProjectSense.log</code>).</li><li>Leave <code>MaxAgeDays</code> at <code>90</code> unless agreed otherwise with the team.</li><li>Test without deleting:</li></ol><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">powershell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NoProfile </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExecutionPolicy Bypass </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">File scripts\\ProjectSense.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ConfigPath config.json </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WhatIf</span></span></code></pre></div><ol start="6"><li>Run once manually to confirm the log looks right:</li></ol><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">powershell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NoProfile </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExecutionPolicy Bypass </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">File scripts\\ProjectSense.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ConfigPath config.json</span></span></code></pre></div><ol start="7"><li>Register automatic runs at login: open <code>shell:startup</code>, create a shortcut with this target (adjust paths):</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>powershell.exe -ep Bypass -WindowStyle hidden C:\\Path\\To\\ProjectSense\\scripts\\ProjectSense.ps1 -ConfigPath C:\\Path\\To\\ProjectSense\\config.json</span></span></code></pre></div><p>Check the log file after the first scheduled run. Full configuration options and troubleshooting are in the <a href="https://gitlab.internal.syslifters.com/tools/project-sense/-/blob/master/README.md" target="_blank" rel="noreferrer">repository README</a>.</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><p>Prerequisites: <code>bash</code>, <code>jq</code>, and optionally <code>notify-send</code> for desktop notifications.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/project-sense.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/project-sense.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --what-if</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # dry run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/project-sense.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # run for real</span></span></code></pre></div><p>Register a daily cron job, for example at 11:00. Use absolute paths:</p><div class="language-cron vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cron</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0 11 * * * /full/path/to/scripts/project-sense.sh --config /full/path/to/config.json</span></span></code></pre></div><p>See <a href="https://gitlab.internal.syslifters.com/tools/project-sense/-/blob/master/config.example.json" target="_blank" rel="noreferrer"><code>config.example.json</code></a> in the repository for path examples.</p><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><p>Prerequisites: <code>bash</code>, <code>jq</code>.</p><p>Cron jobs are unreliable on macOS, so use the LaunchAgent template in the repository instead.</p><p>Install Project Sense outside protected folders (<code>~/Documents</code>, <code>~/Desktop</code>, <code>~/Downloads</code>), for example <code>~/ProjectSense</code>. The same applies to <code>Logfile</code> and <code>ObservationRoots</code> in <code>config.json</code>.</p><ol><li>Test without deleting:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/project-sense.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/project-sense.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --what-if</span></span></code></pre></div><ol start="2"><li>Run once manually to confirm the log looks right:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/project-sense.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.json</span></span></code></pre></div><ol start="3"><li>Edit <a href="https://gitlab.internal.syslifters.com/tools/project-sense/-/blob/master/launchd/com.project-sense.plist" target="_blank" rel="noreferrer"><code>launchd/com.project-sense.plist</code></a>: set the script and config paths. Keep <code>WorkingDirectory</code> as <code>/tmp</code>.</li><li>Install and load the LaunchAgent:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launchd/com.project-sense.plist</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/LaunchAgents/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">launchctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootstrap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gui/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">id</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">~/Library/LaunchAgents/com.project-sense.plist</span></span></code></pre></div><ol start="5"><li>Trigger a test run:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">launchctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kickstart</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gui/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">id</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/com.project-sense</span></span></code></pre></div><p>The job runs daily at 11:00 while you are logged in. Debug output goes to <code>/tmp/project-sense.launchd.err.log</code>.</p><p>After changing the plist, reload it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">launchctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gui/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">id</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/com.project-sense</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">launchctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootstrap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gui/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">id</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">~/Library/LaunchAgents/com.project-sense.plist</span></span></code></pre></div><p>If the job fails, check the err log, use absolute paths everywhere, ensure the plist <code>PATH</code> includes <code>/opt/homebrew/bin</code> if you use Homebrew.</p><p>See <a href="https://gitlab.internal.syslifters.com/tools/project-sense/-/blob/master/config.example.json" target="_blank" rel="noreferrer"><code>config.example.json</code></a> in the repository for path examples.</p><h2 id="before-you-rely-on-it" tabindex="-1">Before you rely on it <a class="header-anchor" href="#before-you-rely-on-it" aria-label="Permalink to &quot;Before you rely on it&quot;">​</a></h2><ul><li>Store pentest files only under your configured observation root(s).</li><li>Run with <code>-WhatIf</code> / <code>--what-if</code> after changing <code>config.json</code> or moving projects.</li><li>Review the log when a project you expected to keep was deleted (usually the newest file was still within 90 days, or <code>SKIP_DELETION</code> was missing).</li><li>Remove customer data from other locations manually; Project Sense only watches the paths you configure.</li></ul>`,41)])])}const g=e(n,[["render",o]]);export{k as __pageData,g as default};
